use alloy_hardforks::EthereumHardforks;
use alloy_primitives::{BlockNumber, BlockTimestamp};
use revm::primitives::hardfork::SpecId;

/// Map the latest active hardfork at the given header to a [`SpecId`].
pub fn spec<C, H>(chain_spec: &C, header: &H) -> SpecId
where
    C: EthereumHardforks,
    H: BlockHeader,
{
    spec_by_timestamp_and_block_number(chain_spec, header.timestamp(), header.number())
}

/// Map the latest active hardfork at the given timestamp or block number to a [`SpecId`].
pub fn spec_by_timestamp_and_block_number<C>(
    chain_spec: &C,
    timestamp: BlockTimestamp,
    block_number: BlockNumber,
) -> SpecId
where
    C: EthereumHardforks,
{
    if chain_spec.is_osaka_active_at_timestamp(timestamp) {
        SpecId::OSAKA
    } else if chain_spec.is_prague_active_at_timestamp(timestamp) {
        SpecId::PRAGUE
    } else if chain_spec.is_cancun_active_at_timestamp(timestamp) {
        SpecId::CANCUN
    } else if chain_spec.is_shanghai_active_at_timestamp(timestamp) {
        SpecId::SHANGHAI
    } else if chain_spec.is_paris_active_at_block(block_number) {
        SpecId::MERGE
    } else if chain_spec.is_london_active_at_block(block_number) {
        SpecId::LONDON
    } else if chain_spec.is_berlin_active_at_block(block_number) {
        SpecId::BERLIN
    } else if chain_spec.is_istanbul_active_at_block(block_number) {
        SpecId::ISTANBUL
    } else if chain_spec.is_petersburg_active_at_block(block_number) {
        SpecId::PETERSBURG
    } else if chain_spec.is_byzantium_active_at_block(block_number) {
        SpecId::BYZANTIUM
    } else if chain_spec.is_spurious_dragon_active_at_block(block_number) {
        SpecId::SPURIOUS_DRAGON
    } else if chain_spec.is_tangerine_whistle_active_at_block(block_number) {
        SpecId::TANGERINE
    } else if chain_spec.is_homestead_active_at_block(block_number) {
        SpecId::HOMESTEAD
    } else {
        SpecId::FRONTIER
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::eth::spec::EthSpec;
    use alloy_consensus::Header;
    use alloy_hardforks::{
        mainnet::{
            MAINNET_BERLIN_BLOCK, MAINNET_BYZANTIUM_BLOCK, MAINNET_CANCUN_TIMESTAMP,
            MAINNET_FRONTIER_BLOCK, MAINNET_HOMESTEAD_BLOCK, MAINNET_ISTANBUL_BLOCK,
            MAINNET_LONDON_BLOCK, MAINNET_PARIS_BLOCK, MAINNET_PETERSBURG_BLOCK,
            MAINNET_PRAGUE_TIMESTAMP, MAINNET_SHANGHAI_TIMESTAMP, MAINNET_SPURIOUS_DRAGON_BLOCK,
            MAINNET_TANGERINE_BLOCK,
        },
        EthereumHardfork, ForkCondition,
    };
    use alloy_primitives::{BlockNumber, BlockTimestamp};

    struct FakeHardfork {
        fork: EthereumHardfork,
        cond: ForkCondition,
    }

    impl FakeHardfork {
        fn osaka() -> Self {
            Self::from_timestamp_zero(EthereumHardfork::Osaka)
        }

        fn prague() -> Self {
            Self::from_timestamp_zero(EthereumHardfork::Prague)
        }

        fn cancun() -> Self {
            Self::from_timestamp_zero(EthereumHardfork::Cancun)
        }

        fn shanghai() -> Self {
            Self::from_timestamp_zero(EthereumHardfork::Shanghai)
        }

        fn paris() -> Self {
            Self::from_block_zero(EthereumHardfork::Paris)
        }

        fn london() -> Self {
            Self::from_block_zero(EthereumHardfork::London)
        }

        fn berlin() -> Self {
            Self::from_block_zero(EthereumHardfork::Berlin)
        }

        fn istanbul() -> Self {
            Self::from_block_zero(EthereumHardfork::Istanbul)
        }

        fn petersburg() -> Self {
            Self::from_block_zero(EthereumHardfork::Petersburg)
        }

        fn spurious_dragon() -> Self {
            Self::from_block_zero(EthereumHardfork::SpuriousDragon)
        }

        fn homestead() -> Self {
            Self::from_block_zero(EthereumHardfork::Homestead)
        }

        fn frontier() -> Self {
            Self::from_block_zero(EthereumHardfork::Frontier)
        }

        fn from_block_zero(fork: EthereumHardfork) -> Self {
            Self { fork, cond: ForkCondition::Block(0) }
        }

        fn from_timestamp_zero(fork: EthereumHardfork) -> Self {
            Self { fork, cond: ForkCondition::Timestamp(0) }
        }
    }

    impl EthereumHardforks for FakeHardfork {
        fn ethereum_fork_activation(&self, fork: EthereumHardfork) -> ForkCondition {
            if fork == self.fork {
                self.cond
            } else {
                ForkCondition::Never
            }
        }
    }

    #[test_case::test_case(FakeHardfork::osaka(), SpecId::OSAKA; "Osaka")]
    #[test_case::test_case(FakeHardfork::prague(), SpecId::PRAGUE; "Prague")]
    #[test_case::test_case(FakeHardfork::cancun(), SpecId::CANCUN; "Cancun")]
    #[test_case::test_case(FakeHardfork::shanghai(), SpecId::SHANGHAI; "Shanghai")]
    #[test_case::test_case(FakeHardfork::paris(), SpecId::MERGE; "Merge")]
    #[test_case::test_case(FakeHardfork::london(), SpecId::LONDON; "London")]
    #[test_case::test_case(FakeHardfork::berlin(), SpecId::BERLIN; "Berlin")]
    #[test_case::test_case(FakeHardfork::istanbul(), SpecId::ISTANBUL; "Istanbul")]
    #[test_case::test_case(FakeHardfork::petersburg(), SpecId::PETERSBURG; "Petersburg")]
    #[test_case::test_case(FakeHardfork::spurious_dragon(), SpecId::SPURIOUS_DRAGON; "Spurious dragon")]
    #[test_case::test_case(FakeHardfork::homestead(), SpecId::HOMESTEAD; "Homestead")]
    #[test_case::test_case(FakeHardfork::frontier(), SpecId::FRONTIER; "Frontier")]
    fn test_spec_maps_hardfork_successfully(fork: impl EthereumHardforks, expected_spec: SpecId) {
        let header = Header::default();
        let actual_spec = spec(&fork, &header);

        assert_eq!(actual_spec, expected_spec);
    }

    #[test_case::test_case(MAINNET_PRAGUE_TIMESTAMP, 0, SpecId::PRAGUE; "Prague")]
    #[test_case::test_case(MAINNET_CANCUN_TIMESTAMP, 0, SpecId::CANCUN; "Cancun")]
    #[test_case::test_case(MAINNET_SHANGHAI_TIMESTAMP, 0, SpecId::SHANGHAI; "Shanghai")]
    #[test_case::test_case(0, MAINNET_PARIS_BLOCK, SpecId::MERGE; "Merge")]
    #[test_case::test_case(0, MAINNET_LONDON_BLOCK, SpecId::LONDON; "London")]
    #[test_case::test_case(0, MAINNET_BERLIN_BLOCK, SpecId::BERLIN; "Berlin")]
    #[test_case::test_case(0, MAINNET_ISTANBUL_BLOCK, SpecId::ISTANBUL; "Istanbul")]
    #[test_case::test_case(0, MAINNET_PETERSBURG_BLOCK, SpecId::PETERSBURG; "Petersburg")]
    #[test_case::test_case(0, MAINNET_BYZANTIUM_BLOCK, SpecId::BYZANTIUM; "Byzantium")]
    #[test_case::test_case(0, MAINNET_SPURIOUS_DRAGON_BLOCK, SpecId::SPURIOUS_DRAGON; "Spurious dragon")]
    #[test_case::test_case(0, MAINNET_TANGERINE_BLOCK, SpecId::TANGERINE; "Tangerine")]
    #[test_case::test_case(0, MAINNET_HOMESTEAD_BLOCK, SpecId::HOMESTEAD; "Homestead")]
    #[test_case::test_case(0, MAINNET_FRONTIER_BLOCK, SpecId::FRONTIER; "Frontier")]
    fn test_eth_spec_maps_hardfork_successfully(
        timestamp: BlockTimestamp,
        number: BlockNumber,
        expected_spec: SpecId,
    ) {
        let fork = EthSpec::mainnet();
        let header = Header { timestamp, number, ..Default::default() };
        let actual_spec = spec(&fork, &header);

        assert_eq!(actual_spec, expected_spec);
    }
}

//! Abstraction over EVM.

use crate::{env::BlockEnvironment, tracing::TxTracer, EvmEnv, EvmError, IntoTxEnv};
use alloy_consensus::transaction::TxHashRef;
use alloy_primitives::{Address, Bytes, B256};
use core::{error::Error, fmt::Debug, hash::Hash};
use revm::{
    context::result::ExecutionResult,
    context_interface::{
        result::{HaltReasonTr, ResultAndState},
        ContextTr,
    },
    inspector::{JournalExt, NoOpInspector},
    DatabaseCommit, Inspector,
};

/// Helper trait to bound [`revm::Database::Error`] with common requirements.
pub trait Database: revm::Database<Error: Error + Send + Sync + 'static> + Debug {}
impl<T> Database for T where T: revm::Database<Error: Error + Send + Sync + 'static> + Debug {}

/// An instance of an ethereum virtual machine.
///
/// An EVM is commonly initialized with the corresponding block context and state and it's only
/// purpose is to execute transactions.
///
/// Executing a transaction will return the outcome of the transaction.
pub trait Evm {
    /// Database type held by the EVM.
    type DB;
    /// The transaction object that the EVM will execute.
    ///
    /// This type represents the transaction environment that the EVM operates on internally.
    /// Typically this is [`revm::context::TxEnv`], which contains all necessary transaction
    /// data like sender, gas limits, value, and calldata.
    ///
    /// The EVM accepts flexible transaction inputs through the [`IntoTxEnv`] trait. This means
    /// that while the EVM internally works with `Self::Tx` (usually `TxEnv`), users can pass
    /// various transaction formats to [`Evm::transact`], including:
    /// - Direct [`TxEnv`](revm::context::TxEnv) instances
    /// - [`Recovered<T>`](alloy_consensus::transaction::Recovered) where `T` implements
    ///   [`crate::FromRecoveredTx`]
    /// - [`WithEncoded<Recovered<T>>`](alloy_eips::eip2718::WithEncoded) where `T` implements
    ///   [`crate::FromTxWithEncoded`]
    ///
    /// This design allows the EVM to accept recovered consensus transactions seamlessly.
    type Tx: IntoTxEnv<Self::Tx>;
    /// Error type returned by EVM. Contains either errors related to invalid transactions or
    /// internal irrecoverable execution errors.
    type Error: EvmError;
    /// Halt reason. Enum over all possible reasons for halting the execution. When execution halts,
    /// it means that transaction is valid, however, it's execution was interrupted (e.g because of
    /// running out of gas or overflowing stack).
    type HaltReason: HaltReasonTr + Send + Sync + 'static;
    /// Identifier of the EVM specification. EVM is expected to use this identifier to determine
    /// which features are enabled.
    type Spec: Debug + Copy + Hash + Eq + Send + Sync + Default + 'static;
    /// Block environment used by the EVM.
    type BlockEnv: BlockEnvironment;
    /// Precompiles used by the EVM.
    type Precompiles;
    /// Evm inspector.
    type Inspector;

    /// Reference to [`Evm::BlockEnv`].
    fn block(&self) -> &Self::BlockEnv;

    /// Returns the chain ID of the environment.
    fn chain_id(&self) -> u64;

    /// Executes a transaction and returns the outcome.
    fn transact_raw(
        &mut self,
        tx: Self::Tx,
    ) -> Result<ResultAndState<Self::HaltReason>, Self::Error>;

    /// Same as [`Evm::transact_raw`], but takes any type implementing [`IntoTxEnv`].
    ///
    /// This is the primary method for executing transactions. It accepts flexible input types
    /// that can be converted to the EVM's transaction environment, including:
    /// - [`TxEnv`](revm::context::TxEnv) - Direct transaction environment
    /// - [`Recovered<T>`](alloy_consensus::transaction::Recovered) - Consensus transaction with
    ///   recovered sender
    /// - [`WithEncoded<Recovered<T>>`](alloy_eips::eip2718::WithEncoded) - Transaction with sender
    ///   and encoded bytes
    ///
    /// The conversion happens automatically through the [`IntoTxEnv`] trait.
    fn transact(
        &mut self,
        tx: impl IntoTxEnv<Self::Tx>,
    ) -> Result<ResultAndState<Self::HaltReason>, Self::Error> {
        self.transact_raw(tx.into_tx_env())
    }

    /// Executes a system call.
    ///
    /// Note: this will only keep the target `contract` in the state. This is done because revm is
    /// loading [`revm::context::Block::beneficiary`] into state by default, and we need to avoid it
    /// by also covering edge cases when beneficiary is set to the system contract address.
    fn transact_system_call(
        &mut self,
        caller: Address,
        contract: Address,
        data: Bytes,
    ) -> Result<ResultAndState<Self::HaltReason>, Self::Error>;

    /// Returns an immutable reference to the underlying database.
    fn db(&self) -> &Self::DB {
        self.components().0
    }

    /// Returns a mutable reference to the underlying database.
    fn db_mut(&mut self) -> &mut Self::DB {
        self.components_mut().0
    }

    /// Executes a transaction and commits the state changes to the underlying database.
    fn transact_commit(
        &mut self,
        tx: impl IntoTxEnv<Self::Tx>,
    ) -> Result<ExecutionResult<Self::HaltReason>, Self::Error>
    where
        Self::DB: DatabaseCommit,
    {
        let ResultAndState { result, state } = self.transact(tx)?;
        self.db_mut().commit(state);

        Ok(result)
    }

    /// Consumes the EVM and returns the inner [`EvmEnv`].
    fn finish(self) -> (Self::DB, EvmEnv<Self::Spec, Self::BlockEnv>)
    where
        Self: Sized;

    /// Consumes the EVM and returns the inner database.
    fn into_db(self) -> Self::DB
    where
        Self: Sized,
    {
        self.finish().0
    }

    /// Consumes the EVM and returns the inner [`EvmEnv`].
    fn into_env(self) -> EvmEnv<Self::Spec, Self::BlockEnv>
    where
        Self: Sized,
    {
        self.finish().1
    }

    /// Determines whether additional transactions should be inspected or not.
    ///
    /// See also [`EvmFactory::create_evm_with_inspector`].
    fn set_inspector_enabled(&mut self, enabled: bool);

    /// Enables the configured inspector.
    ///
    /// All additional transactions will be inspected if enabled.
    fn enable_inspector(&mut self) {
        self.set_inspector_enabled(true)
    }

    /// Disables the configured inspector.
    ///
    /// Transactions will no longer be inspected.
    fn disable_inspector(&mut self) {
        self.set_inspector_enabled(false)
    }

    /// Getter of precompiles.
    fn precompiles(&self) -> &Self::Precompiles {
        self.components().2
    }

    /// Mutable getter of precompiles.
    fn precompiles_mut(&mut self) -> &mut Self::Precompiles {
        self.components_mut().2
    }

    /// Getter of inspector.
    fn inspector(&self) -> &Self::Inspector {
        self.components().1
    }

    /// Mutable getter of inspector.
    fn inspector_mut(&mut self) -> &mut Self::Inspector {
        self.components_mut().1
    }

    /// Provides immutable references to the database, inspector and precompiles.
    fn components(&self) -> (&Self::DB, &Self::Inspector, &Self::Precompiles);

    /// Provides mutable references to the database, inspector and precompiles.
    fn components_mut(&mut self) -> (&mut Self::DB, &mut Self::Inspector, &mut Self::Precompiles);
}

/// An extension trait for [`Evm`] providing additional functionality.
pub trait EvmExt: Evm {
    /// Replays all the transactions until the target transaction is found.
    ///
    /// This stops before transacting the target hash and commits all previous changes.
    ///
    /// Returns the index of the target transaction in the iterator.
    fn replay_transactions_until<I, T>(
        &mut self,
        transactions: I,
        target_tx_hash: B256,
    ) -> Result<usize, Self::Error>
    where
        Self::DB: DatabaseCommit,
        I: IntoIterator<Item = T>,
        T: IntoTxEnv<Self::Tx> + TxHashRef,
    {
        let mut index = 0;
        for tx in transactions {
            if *tx.tx_hash() == target_tx_hash {
                // reached the target transaction
                break;
            }
            self.transact_commit(tx)?;
            index += 1;
        }
        Ok(index)
    }

    /// Replays all the previous transactions and returns the [`ResultAndState`] of the target
    /// transaction.
    ///
    /// Returns `None` if the target transaction was not found.
    fn replay_transaction<I, T>(
        &mut self,
        transactions: I,
        target_tx_hash: B256,
    ) -> Result<Option<ResultAndState<Self::HaltReason>>, Self::Error>
    where
        Self::DB: DatabaseCommit,
        I: IntoIterator<Item = T>,
        T: IntoTxEnv<Self::Tx> + TxHashRef,
    {
        for tx in transactions {
            if *tx.tx_hash() == target_tx_hash {
                // reached the target transaction
                return self.transact(tx).map(Some);
            } else {
                self.transact_commit(tx)?;
            }
        }
        Ok(None)
    }
}

/// Automatic implementation of [`EvmExt`] for all types that implement [`Evm`].
impl<T: Evm> EvmExt for T {}

/// A type responsible for creating instances of an ethereum virtual machine given a certain input.
pub trait EvmFactory {
    /// The EVM type that this factory creates.
    type Evm<DB: Database, I: Inspector<Self::Context<DB>>>: Evm<
        DB = DB,
        Tx = Self::Tx,
        HaltReason = Self::HaltReason,
        Error = Self::Error<DB::Error>,
        Spec = Self::Spec,
        BlockEnv = Self::BlockEnv,
        Precompiles = Self::Precompiles,
        Inspector = I,
    >;

    /// The EVM context for inspectors
    type Context<DB: Database>: ContextTr<Db = DB, Journal: JournalExt>;
    /// Transaction environment.
    type Tx: IntoTxEnv<Self::Tx>;
    /// EVM error. See [`Evm::Error`].
    type Error<DBError: Error + Send + Sync + 'static>: EvmError;
    /// Halt reason. See [`Evm::HaltReason`].
    type HaltReason: HaltReasonTr + Send + Sync + 'static;
    /// The EVM specification identifier, see [`Evm::Spec`].
    type Spec: Debug + Copy + Hash + Eq + Send + Sync + Default + 'static;
    /// Block environment used by the EVM. See [`Evm::BlockEnv`].
    type BlockEnv: BlockEnvironment;
    /// Precompiles used by the EVM.
    type Precompiles;

    /// Creates a new instance of an EVM.
    fn create_evm<DB: Database>(
        &self,
        db: DB,
        evm_env: EvmEnv<Self::Spec, Self::BlockEnv>,
    ) -> Self::Evm<DB, NoOpInspector>;

    /// Creates a new instance of an EVM with an inspector.
    ///
    /// Note: It is expected that the [`Inspector`] is usually provided as `&mut Inspector` so that
    /// it remains owned by the call site when [`Evm::transact`] is invoked.
    fn create_evm_with_inspector<DB: Database, I: Inspector<Self::Context<DB>>>(
        &self,
        db: DB,
        input: EvmEnv<Self::Spec, Self::BlockEnv>,
        inspector: I,
    ) -> Self::Evm<DB, I>;
}

/// An extension trait for [`EvmFactory`] providing useful non-overridable methods.
pub trait EvmFactoryExt: EvmFactory {
    /// Creates a new [`TxTracer`] instance with the given database, input and fused inspector.
    fn create_tracer<DB, I>(
        &self,
        db: DB,
        input: EvmEnv<Self::Spec, Self::BlockEnv>,
        fused_inspector: I,
    ) -> TxTracer<Self::Evm<DB, I>>
    where
        DB: Database + DatabaseCommit,
        I: Inspector<Self::Context<DB>> + Clone,
    {
        TxTracer::new(self.create_evm_with_inspector(db, input, fused_inspector))
    }
}

impl<T: EvmFactory> EvmFactoryExt for T {}

